// ─── File: pages/TransferPage.ts ───
import { Page, Locator } from '@playwright/test';

export class TransferPage {
  readonly page: Page;

  constructor(page: Page) { this.page = page; }

  // getByRole: BEST — reliable, accessibility-aligned, readable.
  // Use for interactive/landmark elements (button, link, heading, textbox).
  transferButton(): Locator {
    return this.page.getByRole('button', { name: 'Transfer' });
  }

  // getByText: GOOD when the visible text IS the identifier (messages, labels).
  // Risk: copy/localization changes can break it; partial a11y alignment.
  successMessage(): Locator {
    return this.page.getByText('Transfer completed', { exact: false });
  }

  // Even better for a message: scope text WITHIN its role for precision.
  successAlert(): Locator {
    return this.page.getByRole('alert').filter({ hasText: /transfer completed/i });
  }

  // Generic locator(): FALLBACK — flexible but least reliable/readable.
  // Only when no role/label/text fits; prefer getByTestId over raw CSS.
  progressSpinner(): Locator {
    // No role/text available on this decorative element.
    return this.page.locator('[data-testid="transfer-progress"]'); // stable-ish via testid
  }

  // Anti-pattern (shown for contrast, do NOT use): brittle structural CSS.
  // return this.page.locator('div.css-1ab2 > span:nth-child(2)');

  async goto() { await this.page.goto('/transfer'); }
}
