// ─── File: tests/locators.spec.ts ───
import { test, expect } from '@playwright/test';
import { TransferPage } from '../pages/TransferPage';

test.describe('locator() vs getByRole() vs getByText()', () => {
  test('role-based click is reliable and readable', async ({ page }) => {
    const t = new TransferPage(page);
    await t.goto();
    await t.transferButton().click();              // getByRole
    await expect(t.successAlert()).toBeVisible();   // role-scoped text
  });

  test('text-based assertion when the words are the identifier', async ({ page }) => {
    const t = new TransferPage(page);
    await t.goto();
    await t.transferButton().click();
    await expect(t.successMessage()).toBeVisible();  // getByText
  });

  test('generic locator only as a scoped fallback', async ({ page }) => {
    const t = new TransferPage(page);
    await t.goto();
    await t.transferButton().click();
    // Decorative element with no role/text — use scoped testid locator.
    await expect(t.progressSpinner()).toBeHidden();  // auto-waits until gone
  });
});
